new file mode 100644
index 0000000..39fe73c
--- /dev/null
+++ b/parallel_help_test.go
@@ -0,0 +1,99 @@
+package cli_test
+
+import (
+	"context"
+	"fmt"
+	"runtime/debug"
+	"testing"
+
+	"github.com/urfave/cli/v3"
+)
+
+func runCliParallelHelp(args []string) {
+	cmd := &cli.Command{
+		Name:  "debug",
+		Usage: "make an explosive entrance",
+		Action: func(_ context.Context, cmd *cli.Command) error {
+			return nil
+		},
+	}
+
+	if err := cmd.Run(context.Background(), args); err != nil {
+		fmt.Printf("%s\n", err)
+	}
+}
+
+type parallelHelpCase struct {
+	Name string
+	Args []string
+}
+
+// Test_run is the reporter's test: two parallel subtests each running an
+// independent, default-configured Command (HideHelp unset) with no args.
+func Test_run(t *testing.T) {
+	t.Parallel()
+
+	tests := []parallelHelpCase{
+		{Name: "hello_world"},
+		{Name: "hello_sunshine"},
+	}
+	for _, tt := range tests {
+		t.Run(tt.Name, func(t *testing.T) {
+			t.Parallel()
+
+			defer func() {
+				if r := recover(); r != nil {
+					t.Errorf("unexpected panic - '%s' passing %s\n%s", r, tt.Args, debug.Stack())
+				}
+			}()
+
+			runCliParallelHelp(tt.Args)
+		})
+	}
+}
+
+// TestParallelRunDefaultHelpNoPanic is the check: independent Commands with
+// default help settings (HideHelp unset), run concurrently with no args, must
+// neither panic nor return an error. Same scenario as Test_run, but with more
+// goroutines released together so it fails in nearly every invocation.
+func TestParallelRunDefaultHelpNoPanic(t *testing.T) {
+	const (
+		workers = 8
+		rounds  = 20000
+	)
+
+	for round := 0; round < rounds; round++ {
+		start := make(chan struct{})
+		results := make(chan string, workers)
+
+		for w := 0; w < workers; w++ {
+			go func() {
+				defer func() {
+					if r := recover(); r != nil {
+						results <- fmt.Sprintf("panic: %v", r)
+					}
+				}()
+
+				cmd := &cli.Command{
+					Name:   "debug",
+					Usage:  "make an explosive entrance",
+					Action: func(context.Context, *cli.Command) error { return nil },
+				}
+
+				<-start
+				if err := cmd.Run(context.Background(), nil); err != nil {
+					results <- fmt.Sprintf("error: %v", err)
+					return
+				}
+				results <- ""
+			}()
+		}
+
+		close(start)
+		for w := 0; w < workers; w++ {
+			if msg := <-results; msg != "" {
+				t.Fatalf("round %d: unexpected %s", round, msg)
+			}
+		}
+	}
+}
